<template><ResourceDrawer :open="visible" title="操作日志详细" :width="780" @close="emit('update:visible',false)"><a-descriptions bordered :column="2" size="small"><a-descriptions-item label="操作模块">{{form.title}}</a-descriptions-item><a-descriptions-item label="业务类型">{{typeLabel}}</a-descriptions-item><a-descriptions-item label="操作时间">{{form.operTime}}</a-descriptions-item><a-descriptions-item label="执行状态"><a-tag :color="form.status===0?'green':'red'">{{form.status===0?'正常':'异常'}}</a-tag></a-descriptions-item><a-descriptions-item label="操作人员">{{form.operName}}</a-descriptions-item><a-descriptions-item label="所属部门">{{form.deptName||'-'}}</a-descriptions-item><a-descriptions-item label="操作地址" :span="2">{{form.operIp}} {{form.operLocation}}</a-descriptions-item><a-descriptions-item label="请求地址" :span="2"><a-tag>{{form.requestMethod}}</a-tag> {{form.operUrl}}</a-descriptions-item><a-descriptions-item label="操作方法" :span="2"><code>{{form.method}}</code></a-descriptions-item><a-descriptions-item label="消耗时间">{{form.costTime}} 毫秒</a-descriptions-item></a-descriptions><CodeBlock title="请求参数" :value="form.operParam" @copy="copyText"/><CodeBlock title="返回参数" :value="form.jsonResult" @copy="copyText"/><a-alert v-if="form.status!==0" type="error" :message="form.errorMsg||'执行异常'" show-icon /></ResourceDrawer></template>
<script setup>
import {defineComponent,h} from 'vue';import {CopyOutlined} from '@ant-design/icons-vue';import ResourceDrawer from '@/components/Antd/ResourceDrawer.vue';import feedback from '@/plugins/antdFeedback'
const {proxy}=getCurrentInstance();const props=defineProps({visible:{type:Boolean,default:false},row:{type:Object,default:()=>({})}});const emit=defineEmits(['update:visible']);const {sys_oper_type}=proxy.useDict('sys_oper_type');const form=computed(()=>props.row||{});const typeLabel=computed(()=>proxy.selectDictLabel(sys_oper_type.value,form.value.businessType)||'-');const formatJson=str=>{if(!str)return '（无数据）';try{return JSON.stringify(JSON.parse(str),null,2)}catch{return str}}
async function copyText(str){const text=formatJson(str);if(navigator.clipboard)await navigator.clipboard.writeText(text);else{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}feedback.msgSuccess('已复制')}
const CodeBlock=defineComponent({props:{title:String,value:[String,Object]},emits:['copy'],setup(p,{emit}){return()=>h('section',{class:'code-section'},[h('header',{},[h('strong',{},p.title),h('button',{type:'button',class:'copy-button',onClick:()=>emit('copy',p.value)},[h(CopyOutlined),' 复制'])]),h('pre',{},formatJson(p.value))])}})
</script><style scoped>.code-section{margin-top:16px;border:1px solid var(--workspace-border)}.code-section header{display:flex;justify-content:space-between;padding:10px 12px;background:var(--workspace-surface-muted)}pre{max-height:240px;margin:0;padding:12px;overflow:auto;white-space:pre-wrap;word-break:break-all}.copy-button{border:0;background:transparent;color:var(--workspace-main);cursor:pointer}</style>
